// Ordena lo que manda ManyChat (External Request del flow "Recibir mensajes", body = Full Contact Data)
// y decide si el bot tiene que responder.
const req = $('Webhook ManyChat').first().json;
const crudo = req.body || {};
const contacto = crudo.contacto && typeof crudo.contacto === 'object'
  ? crudo.contacto
  : (crudo.custom_fields && crudo.id !== undefined ? crudo : null);

// custom_fields puede venir como objeto {campo: valor} o como lista [{name, value}]
let cf = contacto?.custom_fields || {};
if (Array.isArray(cf)) cf = Object.fromEntries(cf.filter((c) => c && c.name).map((c) => [c.name, c.value]));

// ManyChat deja "{{...}}" o vacío cuando una variable no tiene valor
function valor(v) {
  if (v === undefined || v === null) return '';
  const s = String(v).trim();
  if (/^\{\{[^}]*\}\}$/.test(s)) return '';
  return s;
}
const primero = (...vs) => vs.map(valor).find(Boolean) || '';

const subscriberId = primero(crudo.subscriber_id, crudo.contact_id, contacto?.id);

// El mensaje que juntó el flow "Recibir mensajes" (respuesta_definitiva → mensaje_a_enviar)
const textoOriginal = primero(crudo.mensaje, crudo.texto, cf.mensaje_a_enviar, cf.respuesta_definitiva,
  contacto?.last_input_text, crudo.last_input_text, req.headers?.mensaje);

// Los audios y fotos llegan como URL dentro del texto (ManyChat guarda la URL en "Last Text Input").
// Puede haber varios en un mismo turno: "hola, https://...ogg, https://...jpg"
const EXT_AUDIO = /\.(ogg|oga|opus|mp3|m4a|aac|amr|wav|weba|mpeg)(\?|#|$)/i;
const EXT_IMAGEN = /\.(jpe?g|png|webp|gif|heic)(\?|#|$)/i;
const HOST_MEDIA = /(manychat|manybot|fbsbx|fbcdn|whatsapp|amazonaws)\./i;
const limpiarUrl = (u) => u.replace(/[),.;:!?'"\]]+$/, '');
const urls = (textoOriginal.match(/https?:\/\/[^\s,]+/gi) || []).map(limpiarUrl);
const adjuntosUrl = [...new Set(urls)]
  .filter((u) => EXT_AUDIO.test(u) || EXT_IMAGEN.test(u) || HOST_MEDIA.test(u))
  .slice(0, 5);

let texto = textoOriginal;
for (const u of adjuntosUrl) texto = texto.split(u).join(' ');
texto = texto.replace(/(\s*,\s*){2,}/g, ', ').replace(/^[\s,]+|[\s,]+$/g, '').replace(/[ \t]{2,}/g, ' ').trim();

const adjuntos = adjuntosUrl.map((url, orden) => ({
  url,
  orden,
  tipo_probable: EXT_AUDIO.test(url) ? 'audio' : (EXT_IMAGEN.test(url) ? 'imagen' : 'otro'),
}));

// bot_activo vacío (contacto nuevo) cuenta como activo
const botActivo = !['no', 'false', '0', 'off', 'n'].includes(valor(cf.bot_activo).toLowerCase());

// Estado que guardó el bot en el turno anterior (vacío = primer contacto)
const estadoAnterior = valor(cf.estado_conversacion).toLowerCase();

// Si llega un aviso con "evento" (versiones viejas de los flows Tomar/Reactivar), no se responde
const esAviso = valor(crudo.evento) !== '';

// Clave para no contestar dos veces el mismo mensaje si ManyChat llama dos veces
function fnv1a(str, seed) {
  let h = seed >>> 0;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h.toString(16).padStart(8, '0');
}
const huella = [subscriberId, contacto?.last_interaction, textoOriginal].map(valor).join('|');
const claveIdempotencia = `otormin:dedupe:${subscriberId}:${fnv1a(huella, 2166136261)}${fnv1a(huella, 33554467)}`;

const nombre = primero(contacto?.name, [valor(crudo.nombre ?? contacto?.first_name), valor(crudo.apellido ?? contacto?.last_name)].filter(Boolean).join(' '));

let motivoNoResponde = '';
if (!subscriberId) motivoNoResponde = 'no vino el contacto';
else if (esAviso) motivoNoResponde = 'es un aviso, no un mensaje del cliente';
else if (!botActivo) motivoNoResponde = 'bot_activo = no (lo atiende un humano)';

return [{
  json: {
    responder: !motivoNoResponde,
    motivo_no_responde: motivoNoResponde,
    subscriber_id: subscriberId,
    nombre,
    telefono: primero(crudo.telefono, contacto?.whatsapp_phone, contacto?.phone),
    texto,
    adjuntos,
    estado_anterior: estadoAnterior,
    es_primer_contacto: !estadoAnterior,
    clave_idempotencia: claveIdempotencia,
  },
}];

// (se ejecuta una vez por adjunto)
// Define si el adjunto es audio, imagen u otra cosa según el archivo descargado,
// y le pone un nombre con extensión válida (Whisper lo necesita).
// Si no se pudo descargar o no es audio ni foto, ya deja el texto para el agente.
const adj = $('Separar adjuntos').item.json;
const bin = $input.item.binary?.data;

if (!bin) {
  return {
    json: {
      tipo_archivo: 'otro',
      orden: adj.orden,
      url: adj.url,
      contenido: '[El cliente mandó un audio o una foto que no se pudo descargar. Pedile con amabilidad que lo reenvíe o que lo escriba.]',
    },
  };
}

const nombre = String(bin.fileName || '');
const ext = (nombre.match(/\.([a-z0-9]+)$/i)?.[1] || '').toLowerCase();
let mime = String(bin.mimeType || '').toLowerCase().split(';')[0].trim();

const MIME_POR_EXT = {
  ogg: 'audio/ogg', oga: 'audio/ogg', opus: 'audio/ogg', mp3: 'audio/mpeg', m4a: 'audio/mp4',
  aac: 'audio/aac', wav: 'audio/wav', amr: 'audio/amr',
  jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png', webp: 'image/webp', gif: 'image/gif',
};
const sinTipo = () => !mime || mime === 'application/octet-stream' || mime === 'binary/octet-stream';
if (sinTipo() && MIME_POR_EXT[ext]) mime = MIME_POR_EXT[ext];
if (sinTipo() && adj.tipo_probable === 'audio') mime = 'audio/ogg';
if (sinTipo() && adj.tipo_probable === 'imagen') mime = 'image/jpeg';
if (mime === 'video/ogg') mime = 'audio/ogg'; // notas de voz que llegan como video/ogg

let tipo = 'otro';
if (mime.startsWith('audio/')) tipo = 'audio';
else if (mime.startsWith('image/')) tipo = 'imagen';

if (tipo === 'otro') {
  return {
    json: {
      tipo_archivo: 'otro',
      orden: adj.orden,
      url: adj.url,
      contenido: `[El cliente mandó un archivo que no es audio ni foto (por ejemplo un documento). Pedile que te cuente qué necesita. Archivo: ${adj.url}]`,
    },
  };
}

const EXT_POR_MIME = {
  'audio/ogg': 'ogg', 'audio/opus': 'ogg', 'audio/mpeg': 'mp3', 'audio/mp3': 'mp3', 'audio/mp4': 'm4a',
  'audio/aac': 'm4a', 'audio/x-m4a': 'm4a', 'audio/wav': 'wav', 'audio/x-wav': 'wav', 'audio/webm': 'webm',
  'audio/amr': 'amr', 'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp', 'image/gif': 'gif',
};
const extFinal = EXT_POR_MIME[mime] || ext || 'bin';
bin.mimeType = mime;
bin.fileName = `${tipo === 'audio' ? 'audio' : 'imagen'}.${extFinal}`;
bin.fileExtension = extFinal;

return { json: { tipo_archivo: tipo, mime, orden: adj.orden, url: adj.url }, binary: { data: bin } };

// (se ejecuta una vez por foto)
// Saca el texto (JSON) que devolvió el análisis de imagen y lo deja listo para el agente.
// Si el análisis falló, deja un texto de respaldo.
const r = $input.item.json || {};
const partes = Object.values(r);
const mensaje = partes.find((p) => p && p.type === 'message') || r['0'] || r;
let analisis = r.error ? '' : (mensaje?.content?.[0]?.text ?? r.content?.[0]?.text ?? r.content ?? r.text ?? '');
analisis = String(typeof analisis === 'string' ? analisis : JSON.stringify(analisis)).replace(/```json|```/g, '').trim();

const contenido = analisis
  ? `[Imagen del cliente] Análisis automático de la foto (JSON): ${analisis}`
  : '[El cliente mandó una foto que no se pudo analizar. Pedile que te cuente qué auto es o qué necesita.]';

return { json: { contenido, orden: $('Preparar archivo').item.json.orden } };

// Junta lo que salió de cada audio y foto, en el orden en que los mandó el cliente
const partes = $input.all()
  .map((i) => i.json)
  .filter((j) => j && typeof j.contenido === 'string' && j.contenido.trim());
partes.sort((a, b) => Number(a.orden ?? 0) - Number(b.orden ?? 0));
return [{ json: { contenido: partes.map((p) => p.contenido.trim()).join('\n') } }];

// query trae: precio_usd, anticipo_pct, cuotas
// La tasa, el anticipo mínimo y los plazos salen del nodo "Configuración Otormín".
const cfg = $('Configuración Otormín').first().json;
const num = (v) => {
  const s = String(v ?? '').replace('%', '').replace(',', '.').trim();
  if (s === '') return NaN;
  const n = Number(s);
  return Number.isFinite(n) ? n : NaN;
};

const tasaAnualPct = num(cfg.TASA_FINANCIACION);
const anticipoMinPct = num(cfg.ANTICIPO_MINIMO);
if (Number.isNaN(tasaAnualPct) || Number.isNaN(anticipoMinPct) || tasaAnualPct < 0 || anticipoMinPct < 0 || anticipoMinPct > 100) {
  return JSON.stringify({
    error: 'financiacion_no_configurada',
    mensaje: 'La tasa o el anticipo mínimo todavía no están cargados. No des números: decile al cliente que un asesor le pasa la propuesta de financiación y usá pedir_humano.',
  });
}

const permitidas = String(cfg.CUOTAS_PERMITIDAS || '12,24,36,48,60')
  .split(',').map(num).filter((n) => n > 0);

const precio = num(query.precio_usd);
if (!(precio > 0)) {
  return 'Error: falta el precio del vehiculo en USD.';
}

let pct = num(query.anticipo_pct);
if (Number.isNaN(pct)) pct = anticipoMinPct;
const anticipoAjustado = pct < anticipoMinPct;
if (pct < anticipoMinPct) pct = anticipoMinPct;
if (pct > 100) pct = 100;

let n = num(query.cuotas);
if (Number.isNaN(n)) n = permitidas.includes(36) ? 36 : permitidas[0];
if (!permitidas.includes(n)) {
  n = permitidas.reduce((a, b) => (Math.abs(b - n) < Math.abs(a - n) ? b : a));
}

const anticipo = Math.round(precio * pct / 100);
const aFinanciar = precio - anticipo;
if (aFinanciar <= 0) {
  return JSON.stringify({ precio_usd: precio, mensaje: 'Con ese anticipo es pago contado, no hay saldo a financiar.' });
}

const i = tasaAnualPct / 100 / 12;
const cuota = i === 0 ? aFinanciar / n : aFinanciar * i / (1 - Math.pow(1 + i, -n));
const total = anticipo + cuota * n;

return JSON.stringify({
  precio_usd: precio,
  anticipo_usd: anticipo,
  anticipo_pct: pct,
  anticipo_minimo_pct: anticipoMinPct,
  anticipo_ajustado_al_minimo: anticipoAjustado,
  monto_a_financiar_usd: aFinanciar,
  cuotas: n,
  cuota_mensual_usd: Math.round(cuota),
  total_a_pagar_usd: Math.round(total),
  tasa_anual_pct: tasaAnualPct,
  planes_disponibles: permitidas,
  aclaracion: 'Cuota estimada. La aprobacion final depende de la evaluacion crediticia.',
});

